INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Gibt es hier nur Testberichte als Ergebnis?', 2, '[{"text": "Nein", "correct": true, "because": "Mehrere dokumentierte Ausgaben"}, {"text": "Ja", "correct": false, "because": "Phasenübergreifende Dokumente"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ergebnis definiert die Projektanforderungen?', 3, '[{"text": "Anforderungsspezifikation", "correct": true, "because": "Anforderungen festlegen"}, {"text": "Entwurfsdokumente", "correct": false, "because": "Design beschreiben"}, {"text": "Testberichte", "correct": false, "because": "Testauswertung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Dokumente gehören zu den Ergebnissen?', 5, '[{"text": "Anforderungsspezifikation", "correct": true, "because": "Projektbasis definieren"}, {"text": "Testberichte", "correct": true, "because": "Qualität nachweisen"}, {"text": "Unstrukturierte Notizen", "correct": false, "because": "Strukturierte Ausgaben"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Entwurfsdokumente beschreiben das System. b) Testberichte sind optional.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Testberichte essenziell"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei diesen Ergebnissen?', 4, '[{"text": "Anforderungsspezifikation", "correct": false, "because": "Projektbasis"}, {"text": "Entwurfsdokumente", "correct": false, "because": "Design festlegen"}, {"text": "Ungeplante Änderungen", "correct": true, "because": "Strukturierter Ansatz"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ich hier ohne Anforderungsspezifikation arbeite?', 2, '[{"text": "Nein", "correct": true, "because": "Anforderungsspezifikation ist Kern"}, {"text": "Ja", "correct": false, "because": "Dokumentation nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ergebnis wähle ich, um das Design festzulegen?', 3, '[{"text": "Entwurfsdokumente", "correct": true, "because": "Systemdesign beschreiben"}, {"text": "Anforderungsspezifikation", "correct": false, "because": "Anforderungen definieren"}, {"text": "Testberichte", "correct": false, "because": "Tests auswerten"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Ausgaben sichern den Projektabschluss?', 5, '[{"text": "Testberichte", "correct": true, "because": "Qualität nachweisen"}, {"text": "Anforderungsspezifikation", "correct": true, "because": "Basis für Abnahme"}, {"text": "Lose Ideen", "correct": false, "because": "Strukturierte Dokumente"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Testberichte validieren das Produkt. b) Entwurfsdokumente sind unwichtig. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Entwurfsdokumente essenziell"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich hier nicht unbedingt?', 4, '[{"text": "Anforderungsspezifikation", "correct": false, "because": "Projektbasis"}, {"text": "Testberichte", "correct": false, "because": "Qualität sichern"}, {"text": "Unstrukturierte Skizzen", "correct": true, "because": "Formale Dokumente nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind Testberichte hier unwichtig?', 2, '[{"text": "Nein", "correct": true, "because": "Validierung des Produkts"}, {"text": "Ja", "correct": false, "because": "Qualitätssicherung zentral"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Ergebnisse unterstützen die Entwicklung?', 4, '[{"text": "Anforderungsspezifikation", "correct": true, "because": "Anforderungen klären"}, {"text": "Entwurfsdokumente", "correct": true, "because": "Design festlegen"}, {"text": "Zufällige Notizen", "correct": false, "because": "Struktur nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass ich hier ohne Spezifikation arbeite. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Anforderungsspezifikation ist Basis"}, {"text": "Ja", "correct": false, "because": "Dokumentation zentral"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich für die Qualitätssicherung?', 3, '[{"text": "Testberichte", "correct": true, "because": "Testergebnisse dokumentieren"}, {"text": "Unstrukturierte Daten", "correct": false, "because": "Struktur nötig"}, {"text": "Keine Dokumentation", "correct": false, "because": "Nachvollziehbarkeit zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Entwurfsdokumente planen das System. b) Spezifikationen sind unwichtig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Spezifikationen essenziell"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile haben diese Ergebnisse?', 5, '[{"text": "Nachvollziehbarkeit", "correct": true, "because": "Dokumentierte Schritte"}, {"text": "Qualitätssicherung", "correct": true, "because": "Testberichte validieren"}, {"text": "Ungeplante Änderungen", "correct": false, "because": "Struktur zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist hier weniger wichtig?', 3, '[{"text": "Anforderungsspezifikation", "correct": false, "because": "Projektbasis"}, {"text": "Testberichte", "correct": false, "because": "Qualität nachweisen"}, {"text": "Unformale Skizzen", "correct": true, "because": "Formale Dokumente nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind Entwurfsdokumente hier unwichtig?', 3, '[{"text": "Nein", "correct": true, "because": "Design festlegen"}, {"text": "Ja", "correct": false, "because": "Entwicklung leiten"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ich hier ohne Testberichte arbeite?', 2, '[{"text": "Nein", "correct": true, "because": "Testberichte sind Kern"}, {"text": "Ja", "correct": false, "because": "Qualitätssicherung zentral"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ergebnis wähle ich für den Projektabschluss?', 4, '[{"text": "Testberichte", "correct": true, "because": "Validierung dokumentieren"}, {"text": "Unstrukturierte Ideen", "correct": false, "because": "Struktur nötig"}, {"text": "Keine Dokumentation", "correct": false, "because": "Nachvollziehbarkeit zählt"}]');
